use std::collections::{HashMap, HashSet};

struct Solution;

impl Solution {
    pub fn is_solvable(words: Vec<String>, result: String) -> bool {
        // Collect all unique characters
        let mut chars = Vec::new();
        let mut char_set = HashSet::new();
        for w in &words {
            for &b in w.as_bytes() {
                let c = b as char;
                if !char_set.contains(&c) {
                    char_set.insert(c);
                    chars.push(c);
                }
            }
        }
        for &b in result.as_bytes() {
            let c = b as char;
            if !char_set.contains(&c) {
                char_set.insert(c);
                chars.push(c);
            }
        }
        if chars.len() > 10 {
            return false; // more than 10 distinct chars cannot be mapped to digits 0-9
        }

        // Leading characters cannot be zero
        let mut leading = HashSet::new();
        for w in &words {
            if let Some(&b) = w.as_bytes().first() {
                leading.insert(b as char);
            }
        }
        if let Some(&b) = result.as_bytes().first() {
            leading.insert(b as char);
        }

        // Precompute the contribution of each character in the sum:
        // sum of words digits - result digits = 0
        // We represent the equation as sum(coeff[c] * digit[c]) = 0
        // where coeff[c] = sum of place values in words - place value in result
        let mut coeff = HashMap::new();

        for w in &words {
            let len = w.len();
            for (i, &b) in w.as_bytes().iter().enumerate() {
                let c = b as char;
                let power = 10_i64.pow((len - 1 - i) as u32);
                *coeff.entry(c).or_insert(0) += power;
            }
        }
        let len = result.len();
        for (i, &b) in result.as_bytes().iter().enumerate() {
            let c = b as char;
            let power = 10_i64.pow((len - 1 - i) as u32);
            *coeff.entry(c).or_insert(0) -= power;
        }

        // Backtracking to assign digits to characters
        let mut used = [false; 10];
        let mut assignment = HashMap::new();

        fn backtrack(
            i: usize,
            chars: &Vec<char>,
            coeff: &HashMap<char, i64>,
            used: &mut [bool; 10],
            assignment: &mut HashMap<char, i64>,
            leading: &HashSet<char>,
        ) -> bool {
            if i == chars.len() {
                // Check if sum(coeff[c] * digit[c]) == 0
                let mut sum = 0_i64;
                for (&c, &v) in assignment.iter() {
                    sum += coeff.get(&c).unwrap_or(&0) * v;
                }
                return sum == 0;
            }
            let c = chars[i];
            for d in 0..10 {
                if used[d] {
                    continue;
                }
                if d == 0 && leading.contains(&c) {
                    continue; // leading digit cannot be zero
                }
                used[d] = true;
                assignment.insert(c, d as i64);
                if backtrack(i + 1, chars, coeff, used, assignment, leading) {
                    return true;
                }
                assignment.remove(&c);
                used[d] = false;
            }
            false
        }

        backtrack(0, &chars, &coeff, &mut used, &mut assignment, &leading)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn example1() {
        let words = vec!["SEND".to_string(), "MORE".to_string()];
        let result = "MONEY".to_string();
        assert_eq!(Solution::is_solvable(words, result), true);
    }

    #[test]
    fn example2() {
        let words = vec!["SIX".to_string(), "SEVEN".to_string(), "SEVEN".to_string()];
        let result = "TWENTY".to_string();
        assert_eq!(Solution::is_solvable(words, result), true);
    }

    #[test]
    fn example3() {
        let words = vec!["LEET".to_string(), "CODE".to_string()];
        let result = "POINT".to_string();
        assert_eq!(Solution::is_solvable(words, result), false);
    }
}

